import { computed, Default, handler, NAME, pattern, UI, Writable } from "commonfabric";

interface Input {
  value: number | Default<0>;
}

const increment = handler<unknown, { value: Writable<number> }>((_, state) => {
  state.value.set(state.value.get() + 1);
});

const decrement = handler<unknown, { value: Writable<number> }>((_, state) => {
  state.value.set(state.value.get() - 1);
});

export default pattern<Input>(({ value }) => {
  return {
    [NAME]: computed(() => `Simple counter: ${value}`),
    [UI]: (
      <div>
        <cf-button onClick={decrement({ value })}>-</cf-button>
        <b>{value}</b>
        <cf-button onClick={increment({ value })}>+</cf-button>
      </div>
    ),
    value,
  };
});
